package com.gymflow.product;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;public record ProductResponse(UUID id,UUID gymId,UUID categoryId,String categoryName,String sku,String name,String description,BigDecimal costPrice,BigDecimal salePrice,int minimumStock,ProductStatus status,Instant createdAt){static ProductResponse from(Product p){return new ProductResponse(p.getId(),p.getGym().getId(),p.getCategory()==null?null:p.getCategory().getId(),p.getCategory()==null?null:p.getCategory().getName(),p.getSku(),p.getName(),p.getDescription(),p.getCostPrice(),p.getSalePrice(),p.getMinimumStock(),p.getStatus(),p.getCreatedAt());}}
